import * as THREE from "three";

import { CAPE_GEO } from "./capeGeo";
import { ELYTRA_GEO } from "./elytraGeo";
import type { ParsedGeo } from "./types";

export interface BackEquipment {
  geo: ParsedGeo;
  side: THREE.Side;
  cropsVanillaSheet: boolean;
  normalizesCape: boolean;
}

const BACK_EQUIPMENT: Record<string, BackEquipment> = {
  CAPE: {
    geo: CAPE_GEO,
    side: THREE.FrontSide,
    cropsVanillaSheet: true,
    normalizesCape: false,
  },
  ELYTRA: {
    geo: ELYTRA_GEO,
    side: THREE.DoubleSide,
    cropsVanillaSheet: false,
    normalizesCape: true,
  },
};

export function backEquipmentFor(type: string): BackEquipment | null {
  return BACK_EQUIPMENT[type.toUpperCase()] ?? null;
}
